import path from "node:path";
import { mkdir, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { runTool } from "../../apps/server/src/media.js";
import type { Config } from "../../apps/server/src/config.js";
export async function generateFixture(c: Config, audio = true) {
  const dir = path.join(c.dataDir, "fixtures");
  await mkdir(dir, { recursive: true });
  const dest = path.join(dir, audio ? "doors-demo.mp4" : "doors-silent.mp4");
  if (existsSync(dest)) return dest;
  const font =
    process.platform === "win32"
      ? "C\\:/Windows/Fonts/arial.ttf"
      : "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf";
  const text = (value: string, y: number, size: number, enable?: string) =>
    `drawtext=fontfile='${font}':text='${value}':fontcolor=white:fontsize=${size}:x=(w-tw)/2:y=${y}${enable ? `:enable='${enable}'` : ""}`;
  const filter = [
    "drawbox=x=0:y=0:w=iw:h=ih:color=0x181427:t=fill",
    text("ORIGINAL SYNTHETIC DEMO", 34, 19),
    text("Which door leads to the treasure?", 90, 33),
    "drawbox=x=235:y=175:w=180:h=230:color=0x793b57:t=fill",
    "drawbox=x=545:y=175:w=180:h=230:color=0x394d8a:t=fill",
    text("A - RED                     B - BLUE", 425, 25),
    text("Make your choice before the reveal", 476, 20, "lt(t,5)"),
    "drawbox=x=545:y=175:w=180:h=230:color=0xcfa94f:t=fill:enable='gte(t,6)'",
    text("The creator opened BLUE. Treasure found.", 476, 25, "gte(t,6)"),
  ].join(",");
  const args = [
    "-y",
    "-v",
    "error",
    "-f",
    "lavfi",
    "-i",
    "color=c=black:s=960x540:r=30:d=12",
  ];
  if (audio)
    args.push(
      "-f",
      "lavfi",
      "-i",
      "sine=frequency=880:sample_rate=48000:duration=12",
    );
  args.push("-vf", filter);
  if (audio)
    args.push("-af", "volume=0:enable='lt(t,6)'", "-c:a", "aac", "-b:a", "96k");
  args.push(
    "-c:v",
    "libx264",
    "-threads",
    "2",
    "-pix_fmt",
    "yuv420p",
    "-movflags",
    "+faststart",
    dest,
  );
  await runTool(c.ffmpeg, args, c.timeout);
  await writeFile(
    path.join(dir, "README.txt"),
    "Original synthetic fixture generated by this project. No external footage.\nSetup 0–5 s, neutral gap 5–6 s, reveal 6–12 s.\nThe creator opens B (blue); treasure appears behind it. Audio outcome tone starts at 6 s.\nDefault cuts: 0, 5, 6, 12 seconds. Human review remains required.\n",
  );
  return dest;
}
